/// Returns the length of the longest common prefix of `a` and `b`.
///
/// Properties:
/// - result <= a.len() and result <= b.len()
/// - a[..result] == b[..result]
/// - if result < a.len() and result < b.len(), then a[result] != b[result]
fn longest_prefix(a: &[i32], b: &[i32]) -> usize {
    let n = a.len().min(b.len());
    for i in 0..n {
        if a[i] != b[i] {
            return i;
        }
    }
    n
}

